            void Add(SkillProgramCatalog catalog,Func<string,bool>?filter=null){foreach(var(id,p)in catalog.Programs.Where(p=>filter?.Invoke(p.Key)??true))b.AddSkill(new(id,catalog.Presentations[id].Name,catalog.Presentations[id].Description){Program=p,ProgramPresentation=catalog.Presentations[id],SelectionWeights=Enum.GetValues<Role>().ToDictionary(role=>role,_=>id==Quiet?10000d:-10000d)});}
            AddBundle("ol-he-qi");AddBundle("ordinary-ding-feng",id=>id=="ol:duanbing");AddBundle("boundary-zhou-yu",id=>id=="boundary:yingzi");AddBundle("boundary-gan-ning",id=>id=="boundary:fenwei");AddBundle("ol-wu-yan");AddBundle("passive-card-rules",id=>id=="classic:hongyan");
            Add(SkillProgramCatalog.Load("""{"schemaVersion":62,"skills":[{"id":"fixture:he-qi-driver","revision":1,"modifiers":[{"id":"actual-own-long-range","query":"attackRange","operation":"add","value":3,"priority":0}],"activations":[{"id":"hongyan","minCards":0,"maxCards":0,"minTargets":0,"maxTargets":0,"targetKind":"otherLiving","usesPerTurn":null,"effects":[{"op":"grantSkills","target":"owner","skillIds":["classic:hongyan"]}]},{"id":"lose-hongyan","minCards":0,"maxCards":0,"minTargets":0,"maxTargets":0,"targetKind":"otherLiving","usesPerTurn":null,"effects":[{"op":"loseOwnerSkillsAndGrant","target":"owner","skillIds":["classic:hongyan"],"sourceBind":"fixture:he-qi-driver"}]},{"id":"draw","minCards":0,"maxCards":0,"minTargets":0,"maxTargets":0,"targetKind":"otherLiving","usesPerTurn":null,"effects":[{"op":"draw","target":"owner","amount":8}]},{"id":"clear","minCards":0,"maxCards":0,"minTargets":0,"maxTargets":0,"targetKind":"otherLiving","usesPerTurn":null,"effects":[{"op":"discardOwnedZoneCards","target":"owner","zones":["equipment"]}]},{"id":"equip-target","minCards":0,"maxCards":0,"minTargets":1,"maxTargets":1,"targetKind":"anyLiving","usesPerTurn":null,"effects":[{"op":"useRandomDeckEquipment","target":"owner","resultBind":"equipment"}]}]},{"id":"fixture:he-qi-quiet","revision":1,"triggers":[{"id":"quiet","window":"afterNormalDraw","subject":"owner","optional":false,"effects":[{"op":"skipTurnPhases","target":"owner","phases":["play"]}]}]}]}""","""{"schemaVersion":3,"skills":{"fixture:he-qi-driver":{"name":"真实装备驱动","description":"原生装备与移动"},"fixture:he-qi-quiet":{"name":"静默","description":"跳过出牌"}}}"""));
            if(paidWatch)
            {
                var watch="""{"schemaVersion":62,"skills":[{"id":"fixture:he-qi-paid-watch","revision":1,"triggers":[{"id":"paid","window":"cardsMoved","subject":"owner","sourceZones":["hand"],"movementReasons":["skill-program.he-qi.DiscardChildren"],"movementOccurrence":"perBatch","optional":false,"usageScope":"game","usageLimit":1,"effects":[{"op":"chooseOption","target":"owner","resultBind":"child","options":[{"id":"continue"}]},{"op":"loseHp","target":"owner","amount":20}]},{"id":"loss","window":"dyingEntering","subject":"owner","optional":false,"usageScope":"game","usageLimit":1,"effects":[{"op":"recover","target":"owner","amount":20},{"op":"loseOwnerSkillsAndGrant","target":"owner","skillIds":["ol:shanxi","fixture:he-qi-paid-watch"],"sourceBind":"fixture:he-qi-driver"}]}]}]}""";
                if(killOwner){var node=System.Text.Json.Nodes.JsonNode.Parse(watch)!;node["skills"]![0]!["triggers"]!.AsArray().RemoveAt(1);watch=node.ToJsonString();}
                Add(SkillProgramCatalog.Load(watch,"""{"schemaVersion":3,"skills":{"fixture:he-qi-paid-watch":{"name":"真实闪付款子链","description":"原生濒死失源或死亡","optionLabels":{"continue":"继续"}}}}"""));
            }
